<template><section class="patient-page"><header class="patient-page-header"><div><p class="eyebrow">FINANCE</p><h1>Payments & Receipts</h1><p class="page-subtitle">ตรวจสอบใบเสร็จและยอดรับชำระ</p></div><button @click="load">รีเฟรช</button></header><p v-if="errorMessage" class="error">{{ errorMessage }}</p><div v-if="loading" class="state-card">กำลังโหลด...</div><div v-else-if="!receipts.length" class="state-card">ยังไม่มีใบเสร็จ</div><div v-else class="patient-results"><article v-for="receipt in receipts" :key="receipt.id" class="patient-result-card"><div><span class="patient-hn">{{ receipt.receiptNumber }} · {{ receipt.branchCode }}</span><h2>{{ receipt.patientName }}</h2><p>{{ new Date(receipt.issuedAt).toLocaleString('th-TH') }}</p></div><div><strong>{{ Number(receipt.paid).toFixed(2) }} บาท</strong><p>{{ receipt.status }}</p><button v-if="receipt.status !== 'VOIDED'" class="secondary" @click="reverse(receipt.id)">ยกเลิกใบเสร็จ</button></div></article></div></section></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { listReceipts, reverseReceipt, type ReceiptSummary } from '@/api/payments'; const receipts=ref<ReceiptSummary[]>([]); const loading=ref(false); const errorMessage=ref(''); async function load(){loading.value=true;errorMessage.value='';try{receipts.value=(await listReceipts()).items}catch(e){errorMessage.value=e instanceof Error?e.message:'เกิดข้อผิดพลาด'}finally{loading.value=false}} async function reverse(id:number){const reason=window.prompt('เหตุผลที่ยกเลิกใบเสร็จ');if(!reason?.trim())return;try{await reverseReceipt(id,reason);await load()}catch(e){errorMessage.value=e instanceof Error?e.message:'เกิดข้อผิดพลาด'}} onMounted(load)</script>
